INSERT INTO brands (id,name,description) VALUES ('depot','DEPOT','Професійний бренд засобів для чоловічого догляду, що поєднує класичні формули із сучасним підходом до очищення, догляду та стайлінгу волосся.') ON CONFLICT(id) DO UPDATE SET name=excluded.name,description=excluded.description;
INSERT INTO product_lines (id,brand_id,name,short_description,description,hair_types,purposes,benefits,keywords,image) VALUES ('depot-100-hair-cleansings','depot','100 Hair Cleansings','Лінійка засобів для очищення волосся та шкіри голови','Засоби для регулярного очищення волосся та шкіри голови з урахуванням різних станів волосся і потреб шкіри голови.','["Нормальне","Жирне","Сухе","Ламке","Світле","Сиве","Знебарвлене"]','["Щоденне очищення","Контроль лупи та себуму","Зволоження","Нейтралізація небажаних теплих тонів"]','["Делікатно очищає","Допомагає підтримувати баланс шкіри голови","Пом’якшує волосся","Освіжає шкіру голови"]','["Очищення","Шампунь","Шкіра голови"]',NULL) ON CONFLICT(id) DO UPDATE SET brand_id=excluded.brand_id,name=excluded.name,short_description=excluded.short_description,description=excluded.description,hair_types=excluded.hair_types,purposes=excluded.purposes,benefits=excluded.benefits,keywords=excluded.keywords,image=excluded.image;
INSERT INTO product_lines (id,brand_id,name,short_description,description,hair_types,purposes,benefits,keywords,image) VALUES ('depot-200-hair-treatments','depot','200 Hair Treatments','Лінійка кондиціонувальних засобів для волосся','Змивний і незмивний догляд для зволоження, пом’якшення, захисту та кращого контролю волосся.','["Усі типи волосся"]','["Кондиціонування","Зволоження","Захист волосся"]','["Пом’якшує волосся","Зменшує статичність","Полегшує укладання"]','["Догляд","Кондиціонер","Зволоження"]',NULL) ON CONFLICT(id) DO UPDATE SET brand_id=excluded.brand_id,name=excluded.name,short_description=excluded.short_description,description=excluded.description,hair_types=excluded.hair_types,purposes=excluded.purposes,benefits=excluded.benefits,keywords=excluded.keywords,image=excluded.image;
INSERT INTO product_lines (id,brand_id,name,short_description,description,hair_types,purposes,benefits,keywords,image) VALUES ('depot-300-hair-stylings','depot','300 Hair Stylings','Лінійка засобів для моделювання та фіксації зачіски','Стайлінгові засоби для створення форми, текстури, об’єму, блиску або матового ефекту з різним рівнем фіксації.','["Тонке"]','["Моделювання зачіски","Фіксація","Текстурування","Надання об’єму"]','["Допомагає контролювати форму","Створює текстуру","Підтримує укладку"]','["Стайлінг","Фіксація","Текстура","Об’єм"]',NULL) ON CONFLICT(id) DO UPDATE SET brand_id=excluded.brand_id,name=excluded.name,short_description=excluded.short_description,description=excluded.description,hair_types=excluded.hair_types,purposes=excluded.purposes,benefits=excluded.benefits,keywords=excluded.keywords,image=excluded.image;
INSERT INTO products (id,brand_id,line_id,name,category,description,purpose,image,usage) VALUES ('depot-101-normalizing-daily-shampoo','depot','depot-100-hair-cleansings','No. 101 Normalizing Daily Shampoo','Шампунь','Нормалізувальний і тонізувальний шампунь із делікатними ПАР без SLES. Підходить для щоденного очищення нормального волосся.','Щоденне делікатне очищення нормального волосся','/images/depot/depot-101-normalizing-daily-shampoo.webp','Нанести на вологе волосся та легко помасажувати шкіру голови. Залишити на кілька хвилин до відчуття свіжості, ретельно змити; за потреби повторити й продовжити догляд кондиціонувальним засобом.') ON CONFLICT(id) DO UPDATE SET brand_id=excluded.brand_id,line_id=excluded.line_id,name=excluded.name,category=excluded.category,description=excluded.description,purpose=excluded.purpose,image=excluded.image,usage=excluded.usage;
