INSERT INTO products (id,brand_id,line_id,name,category,description,purpose,image,usage) VALUES ('depot-102-anti-dandruff-sebum-control-shampoo','depot','depot-100-hair-cleansings','No. 102 Anti-Dandruff & Sebum Control Shampoo','Шампунь','Шампунь із делікатними ПАР без SLES для жирного волосся та шкіри голови, схильної до лупи. Допомагає зменшувати надлишок себуму й відновлювати баланс шкіри голови та волосся.','Контроль лупи та надлишкового себуму','/images/depot/depot-102-anti-dandruff-sebum-control-shampoo.webp','Нанести на вологе волосся та легко помасажувати шкіру голови. Залишити на кілька хвилин, ретельно змити; за потреби повторити.') ON CONFLICT(id) DO UPDATE SET brand_id=excluded.brand_id,line_id=excluded.line_id,name=excluded.name,category=excluded.category,description=excluded.description,purpose=excluded.purpose,image=excluded.image,usage=excluded.usage;
