INSERT INTO products (id,brand_id,line_id,name,category,description,purpose,image,usage) VALUES ('depot-201-refreshing-conditioner','depot','depot-200-hair-treatments','No. 201 Refreshing Conditioner','Кондиціонер','Тонізувальний і зволожувальний кондиціонер, що освіжає шкіру голови та волосся. Пом’якшує й ущільнює волосся та діє як антистатик.','Зволоження, пом’якшення та освіження волосся і шкіри голови','/images/depot/depot-201-refreshing-conditioner.webp','Нанести на підсушене рушником волосся. Масажними рухами розподілити по шкірі голови та волоссю, залишити на кілька хвилин і ретельно змити.') ON CONFLICT(id) DO UPDATE SET brand_id=excluded.brand_id,line_id=excluded.line_id,name=excluded.name,category=excluded.category,description=excluded.description,purpose=excluded.purpose,image=excluded.image,usage=excluded.usage;
