INSERT INTO products (id,brand_id,line_id,name,category,description,purpose,image,usage) VALUES ('depot-202-complete-leave-in-conditioner','depot','depot-200-hair-treatments','No. 202 Complete Leave-in Conditioner','Незмивний кондиціонер','Багатофункціональний незмивний кондиціонер для волосся, який зволожує, кондиціонує, захищає та полегшує контроль під час укладання.','Незмивне кондиціонування та захист волосся','/images/depot/depot-202-complete-leave-in-conditioner.webp','Взяти на руки кількість засобу відповідно до довжини й густоти волосся. Рівномірно нанести на чисте, підсушене рушником волосся, не змивати та продовжити укладання.') ON CONFLICT(id) DO UPDATE SET brand_id=excluded.brand_id,line_id=excluded.line_id,name=excluded.name,category=excluded.category,description=excluded.description,purpose=excluded.purpose,image=excluded.image,usage=excluded.usage;
