INSERT INTO products (id,brand_id,line_id,name,category,description,purpose,image,usage) VALUES ('depot-302-clay-pomade','depot','depot-300-hair-stylings','No. 302 Clay Pomade','Глиняна помада','Моделювальна помада з натуральною глиною для створення форми, розділення пасом і напівматового ефекту. Допомагає надавати тонкому волоссю текстуру й об’єм.','Моделювання текстурної укладки з напівматовим ефектом','/images/depot/depot-302-clay-pomade.webp','Взяти потрібну кількість засобу, розігріти в руках і масажними рухами нанести на сухе волосся для укладання.') ON CONFLICT(id) DO UPDATE SET brand_id=excluded.brand_id,line_id=excluded.line_id,name=excluded.name,category=excluded.category,description=excluded.description,purpose=excluded.purpose,image=excluded.image,usage=excluded.usage;
