INSERT INTO products (id,brand_id,line_id,name,category,description,purpose,image,usage) VALUES ('depot-303-modelling-wax','depot','depot-300-hair-stylings','No. 303 Modelling Wax','Моделювальний віск','Водорозчинний моделювальний віск для сильної, але гнучкої фіксації. Дає змогу змінювати укладку протягом дня після повторної активації водою.','Гнучка фіксація з можливістю рестайлінгу','/images/depot/depot-303-modelling-wax.webp','Нанести потрібну кількість засобу на підсушене рушником або сухе волосся та виконати бажану укладку. Для рестайлінгу змочити руки водою й опрацювати волосся, щоб активувати віск.') ON CONFLICT(id) DO UPDATE SET brand_id=excluded.brand_id,line_id=excluded.line_id,name=excluded.name,category=excluded.category,description=excluded.description,purpose=excluded.purpose,image=excluded.image,usage=excluded.usage;
