INSERT INTO products (id,brand_id,line_id,name,category,description,purpose,image,usage) VALUES ('depot-304-hold-strong-gel','depot','depot-300-hair-stylings','No. 304 Hold Strong Gel','Гель для стайлінгу','Гель сильної фіксації, який надає блиску й допомагає підтримувати укладку протягом дня. Для ефекту мокрого волосся забезпечує максимальний блиск.','Сильна фіксація блискучої укладки','/images/depot/depot-304-hold-strong-gel.webp','Нанести потрібну кількість засобу на підсушене рушником або сухе волосся та виконати бажану укладку. Для рестайлінгу змочити руки водою й опрацювати волосся, щоб активувати гель.') ON CONFLICT(id) DO UPDATE SET brand_id=excluded.brand_id,line_id=excluded.line_id,name=excluded.name,category=excluded.category,description=excluded.description,purpose=excluded.purpose,image=excluded.image,usage=excluded.usage;
